using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedCategory { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

public class TicketInput
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public class PredictionResult
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> Scores { get; set; } = new();
}

public class EvaluationMetrics
{
    public double MicroAccuracy { get; set; }
    public double MacroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private ITransformer _model;
    private PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private EvaluationMetrics _metrics;
    private string[] _categoryLabels = [];

    public EvaluationMetrics Metrics => _metrics;

    public TicketClassifierService()
    {
        _mlContext = new MLContext(seed: 42);
        _metrics = new EvaluationMetrics();
        TrainModel();
    }

    private void TrainModel()
    {
        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        if (!File.Exists(dataPath))
            dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "tickets.csv");

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // Train/test split for evaluation
        var splitData = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.3);
        _model = pipeline.Fit(splitData.TrainSet);

        // Evaluate
        var predictions = _model.Transform(splitData.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");
        _metrics = new EvaluationMetrics
        {
            MicroAccuracy = metrics.MicroAccuracy,
            MacroAccuracy = metrics.MacroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction
        };

        // Retrain on full data for production predictions
        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract category labels from the model's key-value mapping
        var schema = _model.GetOutputSchema(dataView.Schema);
        var labelColumn = schema.GetColumnOrNull("Label");
        if (labelColumn.HasValue)
        {
            var keyValues = new VBuffer<ReadOnlyMemory<char>>();
            labelColumn.Value.GetKeyValues(ref keyValues);
            _categoryLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
        }
    }

    public PredictionResult Predict(TicketInput input)
    {
        var ticketData = new TicketData
        {
            Subject = input.Subject,
            Description = input.Description,
            Priority = input.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
        {
            scores[_categoryLabels[i]] = prediction.Score[i];
        }

        return new PredictionResult
        {
            PredictedCategory = prediction.PredictedCategory,
            Scores = scores
        };
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly TicketClassifierService _classifierService;

    public TicketController(TicketClassifierService classifierService)
    {
        _classifierService = classifierService;
    }

    [HttpPost("classify")]
    public ActionResult<PredictionResult> Classify([FromBody] TicketInput input)
    {
        if (string.IsNullOrWhiteSpace(input.Subject) && string.IsNullOrWhiteSpace(input.Description))
            return BadRequest("Subject or Description is required.");

        if (input.Priority < 1 || input.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        var result = _classifierService.Predict(input);
        return Ok(result);
    }

    [HttpGet("metrics")]
    public ActionResult<EvaluationMetrics> GetMetrics()
    {
        return Ok(_classifierService.Metrics);
    }
}

