// Evaluate using cross-validation (better for small datasets)
var cvResults = _mlContext.MulticlassClassification.CrossValidate(
    dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");
var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);
var avgLogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction);
_metrics = new EvaluationMetrics
{
    MicroAccuracy = avgMicro,
    MacroAccuracy = avgMacro,
    LogLoss = avgLogLoss,
    LogLossReduction = double.IsInfinity(avgLogLossReduction) || double.IsNaN(avgLogLossReduction)
        ? 0 : avgLogLossReduction
};

